(()=>{'use strict';const main=document.querySelector('main');if(!main)return;const host=document.createElement('section');host.className='panel resistance-report';host.id='resistanceReportPanels';host.innerHTML='<h2>重要菌種抗藥性與多重抗藥菌趨勢</h2><p class="small">採年報分類比較與歷年比較方式，僅顯示已核對的精確數值；沒有數值的年度不補值。</p><div class="resist-tabs"><button id="resImportant" aria-pressed="true">重要菌種抗藥性</button><button id="resMdro" aria-pressed="false">多重抗藥菌趨勢</button></div><div class="resist-filters"><label>菌種／指標<select id="resIndicator"></select></label><label id="resSpecimenLabel">檢體別<select id="resSpecimen"><option value="both">血液與尿液比較</option><option value="blood">血液</option><option value="urine">尿液</option></select></label><label id="resYearLabel">年度<select id="resYear"><option value="2024">113 年（2024）</option></select></label></div><p id="resStatus" class="small" role="status" aria-live="polite"></p><div id="resChart" class="res-chart" role="region" aria-label="抗藥性百分比比較圖"></div><div class="resist-actions"><button id="resTableBtn">顯示資料表</button><button id="resCsvBtn">下載 CSV</button></div><div id="resTable" class="scroll" hidden></div><p class="small">資料來源：2024 年版《臺灣抗生素抗藥性監視年報》；圖表數值為抗藥性 R%，與 Antibiogram 的敏感性 S% 不同。年報內文未提供分母時，不顯示信賴區間。</p>';const advanced=[...main.querySelectorAll('.panel')].find(e=>e.textContent.includes('進階分析'));if(advanced)advanced.before(host);else main.append(host);
const $=id=>document.getElementById(id),safe=x=>String(x??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));let data=[],tab='important';
function parse(s){let a=s.trim().split(/\r?\n/),h=a.shift().split(',');return a.map(row=>{let cells=row.split(',');return Object.fromEntries(h.map((key,i)=>[key,cells[i]]))}).filter(r=>Number.isFinite(Number(r.resistance_pct))&&Number(r.resistance_pct)>=0&&Number(r.resistance_pct)<=100)}
const options={important:[['KPN_CAZ','K. pneumoniae / Ceftazidime'],['KPN_SXT','K. pneumoniae / Co-trimoxazole']],mdro:[['CRAB','CRAB'],['CRKP','CRKP'],['CRPA','CRPA']]};
function switchTab(t){tab=t;$('resImportant').setAttribute('aria-pressed',String(t==='important'));$('resMdro').setAttribute('aria-pressed',String(t==='mdro'));$('resIndicator').innerHTML=options[t].map(([v,label])=>'<option value="'+v+'">'+safe(label)+'</option>').join('');$('resSpecimenLabel').hidden=t==='mdro';$('resYearLabel').hidden=t==='mdro';draw()}
function current(){let sel=$('resIndicator').value,rec=data.filter(r=>r.domain===tab&&r.indicator===sel);if(tab==='important'&&$('resSpecimen').value!=='both')rec=rec.filter(r=>r.specimen===$('resSpecimen').value);return rec.sort((a,b)=>Number(a.year)-Number(b.year))}
function draw(){const rows=current(),isMdro=tab==='mdro',barColors=['#588bb9','#dc7947'];$('resStatus').textContent=isMdro?'僅顯示年報明確記載的 108、113 年端點；中間年度資料尚未匯入，不以連線或插值冒充完整歷年趨勢。':'113 年 K. pneumoniae 不同檢體抗藥率比較（年報圖 3-2-3 A）。';if(!rows.length){$('resChart').innerHTML='<p>無符合條件之核對資料。</p>';return}let max=100,W=780,H=330,L=70,T=18,B=62,R=20,ih=H-T-B,base=T+ih;let svg='<svg viewBox="0 0 '+W+' '+H+'" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="'+(isMdro?'MDRO 已核對年度端點':'菌種不同檢體抗藥率比較')+'"><rect width="'+W+'" height="'+H+'" fill="#fff"/>';for(let v=0;v<=100;v+=20){let yy=base-ih*v/100;svg+='<text x="'+(L-8)+'" y="'+(yy+4)+'" text-anchor="end" font-size="13" fill="#222">'+v+'%</text><line x1="'+L+'" x2="'+(W-R)+'" y1="'+yy+'" y2="'+yy+'" stroke="#ddd"/>'}const labels=isMdro?['108年','113年']:rows.map(r=>r.specimen==='blood'?'血液':'尿液');const positions=isMdro?[L+180,L+510]:rows.map((_,i)=>L+(W-L-R)*(i+.5)/rows.length);rows.forEach((r,i)=>{const x=positions[i],height=ih*(+r.resistance_pct)/100,y=base-height;svg+='<rect tabindex="0" x="'+(x-48)+'" y="'+y+'" width="96" height="'+height+'" fill="'+barColors[isMdro?0:i%2]+'" role="img" aria-label="'+safe(labels[i]+' 抗藥率 '+r.resistance_pct+'%')+'"><title>'+safe((isMdro?r.indicator:labels[i])+'：'+r.resistance_pct+'%；來源圖 '+r.source_figure+'，第 '+r.printed_page+' 頁')+'</title></rect><text x="'+x+'" y="'+(y-9)+'" fill="#222" text-anchor="middle" font-size="16" font-weight="bold">'+r.resistance_pct+'%</text><text x="'+x+'" y="'+(base+28)+'" fill="#222" text-anchor="middle" font-size="14">'+safe(labels[i])+'</text>'});svg+='</svg>';$('resChart').innerHTML=svg;$('resTable').innerHTML='<table><caption>年報抗藥性百分比及出處</caption><thead><tr><th scope="col">年度</th><th scope="col">指標</th><th scope="col">檢體</th><th scope="col">R%</th><th scope="col">圖號</th><th scope="col">頁碼</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+safe(r.year)+'</td><td>'+safe(r.indicator)+'</td><td>'+safe(r.specimen)+'</td><td>'+safe(r.resistance_pct)+'%</td><td>'+safe(r.source_figure)+'</td><td>'+safe(r.printed_page)+'</td></tr>').join('')+'</tbody></table>'}
$('resImportant').onclick=()=>switchTab('important');$('resMdro').onclick=()=>switchTab('mdro');$('resIndicator').onchange=draw;$('resSpecimen').onchange=draw;$('resTableBtn').onclick=()=>{$('resTable').hidden=!$('resTable').hidden;$('resTableBtn').textContent=$('resTable').hidden?'顯示資料表':'隱藏資料表'};$('resCsvBtn').onclick=()=>{let h=['domain','indicator','organism','antibiotic','specimen','onset','year','resistance_pct','precision','source_figure','printed_page','notes'],csv='\uFEFF'+h.join(',')+'\n'+current().map(r=>h.map(k=>'"'+String(r[k]||'').replaceAll('"','""')+'"').join(',')).join('\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='ar-'+tab+'-reported-values.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)};
fetch('./data/ar_2024_key_resistance_report_points.csv',{cache:'no-store'}).then(r=>r.ok?r.text():Promise.reject(Error('HTTP '+r.status))).then(t=>{data=parse(t);switchTab('important')}).catch(e=>$('resStatus').textContent='無法載入年報抗藥性數值：'+e.message);
})();